#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    /* Simple postfix (Reverse Polish) expression evaluator.
       It reproduces the observable behavior of the original binary:
       - Operands are signed decimal integers.
       - Supported binary operators: + - * /
       - Tokens are taken from the command line (argv[1] .. argv[argc-1]).
       - A token that is a single character and one of the operators is treated as an operator.
       - Anything else is parsed as a number using strtol; if parsing fails, it is an error.
       - Errors (invalid token, insufficient operands, division by zero, stack overflow,
         empty input, or final stack size not equal to one) cause the program to print
         "ERROR" (followed by a newline) and exit.
       - On success the result (the sole value on the stack) is printed as a signed
         decimal integer followed by a newline.
    */
    const int MAX_STACK = 64;          // matches the original's 0x3f limit
    long stack[MAX_STACK];
    int top = 0;

    if (argc < 2) {
        puts("ERROR");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *tok = argv[i];
        size_t len = strlen(tok);
        if (len == 1 && strchr("+-*/", tok[0])) {
            /* operator */
            if (top < 2) { puts("ERROR"); return 0; }
            long right = stack[--top];
            long left  = stack[--top];
            long result;
            switch (tok[0]) {
                case '+': result = left + right; break;
                case '-': result = left - right; break;
                case '*': result = left * right; break;
                case '/':
                    if (right == 0) { puts("ERROR"); return 0; }
                    result = left / right; break;
                default:  /* never reached */ result = 0; break;
            }
            if (top >= MAX_STACK) { puts("ERROR"); return 0; }
            stack[top++] = result;
        } else {
            /* number */
            char *endptr;
            long val = strtol(tok, &endptr, 10);
            if (endptr == tok || *endptr != '\0') { puts("ERROR"); return 0; }
            if (top >= MAX_STACK) { puts("ERROR"); return 0; }
            stack[top++] = val;
        }
    }

    if (top != 1) {
        puts("ERROR");
        return 0;
    }
    printf("%ld\n", stack[0]);
    return 0;
}
